# Writes the hedra command files of every moving prop of Sprout Jump (each a game bone, its origin at
# the pivot game.as places): seed, pop, shellbug, moth, bloomspring, raft, plank, bloom, pennant, puff,
# water, hills, grove, cloud. Run from models/env: /usr/bin/python3 make_env.py
# hedra is up Z, front -Y; the GLB comes out Y up, front +Z (towards the game's camera at yaw 0).
import random

C = {"Seed": "#fbf236", "Stripe": "#8a6f30", "Spark": "#ffffff", "Shell": "#76428a", "Spot": "#d77bba",
     "Head": "#222034", "BugEye": "#eec39a", "Moth": "#847e87", "Wing": "#cbdbfc", "WingSpot": "#76428a",
     "Petal": "#d95763", "Pink": "#d77bba", "Gold": "#fbf236", "Stalk": "#37946e", "Leafy": "#6abe30",
     "Wood": "#8f563b", "Rope": "#d9a066", "Banner": "#d95763", "Puff": "#cbdbfc", "Deep": "#306082",
     "Pad": "#37946e", "Hill": "#306082", "HillTop": "#37946e", "Grove": "#4b692f", "Cloud": "#cbdbfc"}
TEX = {"Ripple": "../level/textures/ripples.png"}


def mat(name):
    if name in TEX:
        return "material new %s --base-color 1 1 1 --no-slot\nmaterial texture %s base-color %s" % (name, name, TEX[name])
    h = C[name]
    return "material new %s --base-color %s --no-slot" % (name, " ".join("%.3f" % (int(h[i:i + 2], 16) / 255) for i in (1, 3, 5)))


def write(name, head, mats, body):
    lines = ["# %s Generated by make_env.py." % head, "new"] + [mat(m) for m in mats] + body + \
            ["select all", "shade flat", "export %s.glb" % name]
    open(name + ".txt", "w").write("\n".join(lines) + "\n")


def part(nm, prim, loc, scale=None, mat_=None, extra=(), rot=None):
    out = ["add mesh %s --name %s --location %s" % (prim, nm, loc)]
    if scale: out += ["scale %s" % scale, "apply --scale"]
    if rot: out += ["set rotation %s" % rot, "apply --rotation"]
    out += ["apply --location"]
    if mat_: out += ["material assign " + mat_]
    return out + list(extra)


def join(keep, others, rename):
    return ["select " + " ".join([keep] + others), "active " + keep, "join", "rename %s %s" % (keep, rename)]


# a sunflower seed, 0.17 wide, 0.28 tall, 0.1 thick, a dark stripe down its middle; pivot at its centre
write("seed", "A sunflower seed pickup.", ["Seed", "Stripe"],
      part("S", "uv-sphere --segments 8 --rings 6 --radius 0.5", "0 0 0", "0.17 0.1 0.28", "Seed") +
      ["active S", "mode edit", 'select vert where "pos.z > 0.08"', "scale 0.55 0.55 1.25", 'select face where "pos.x < 0.03 && pos.x > -0.03"',
       "material assign Stripe", "mode object"])

# a sparkle: four rays round a centre (the seed pop), unlit
write("pop", "A pickup sparkle.", ["Spark"],
      part("A", "cube --size 1", "0 0 0", "0.6 0.06 0.08", "Spark") +
      part("B", "cube --size 1", "0 0 0", "0.08 0.06 0.6", "Spark") +
      part("C", "cube --size 1", "0 0 0", "0.32 0.06 0.06", "Spark", rot="0 45 0") +
      part("D", "cube --size 1", "0 0 0", "0.32 0.06 0.06", "Spark", rot="0 -45 0") + join("A", ["B", "C", "D"], "Pop"))

# a shellbug: a purple dome shell with two pink spots, a dark head with pale eyes, six stubby legs;
# 0.64 long, 0.42 tall; faces -Y (the GLB's +Z front); pivot on the ground under its middle
bug = (part("Shell", "uv-sphere --segments 10 --rings 6 --radius 0.5", "0 0.04 0.12", "0.5 0.56 0.56", "Shell") +
       ["active Shell", "mode edit", 'select face where "pos.z < -0.02"', "delete only-faces", "mode object"] +
       part("SpotA", "ico-sphere --subdivisions 1 --radius 0.5", "0.12 0.0 0.36", "0.13 0.15 0.08", "Spot") +
       part("SpotB", "ico-sphere --subdivisions 1 --radius 0.5", "-0.12 0.12 0.33", "0.13 0.15 0.08", "Spot") +
       part("Head", "uv-sphere --segments 8 --rings 5 --radius 0.5", "0 -0.27 0.17", "0.26 0.2 0.22", "Head") +
       part("EyeR", "cube --size 1", "-0.065 -0.37 0.21", "0.06 0.04 0.07", "BugEye") +
       part("EyeL", "cube --size 1", "0.065 -0.37 0.21", "0.06 0.04 0.07", "BugEye"))
legs = []
for i, y in enumerate((-0.14, 0.04, 0.2)):
    for sx in (-1, 1):
        nm = "Leg%d%s" % (i, "L" if sx > 0 else "R")
        bug += part(nm, "cube --size 1", "%.3f %.3f 0.05" % (sx * 0.23, y), "0.08 0.06 0.1", "Head")
        legs.append(nm)
write("shellbug", "A shellbug: the garden's patrolling critter.", ["Shell", "Spot", "Head", "BugEye"],
      bug + join("Shell", ["SpotA", "SpotB", "Head", "EyeR", "EyeL"] + legs, "Bug"))

# a moth: a grey fuzzy body and two pale wings raised over its back (broad faces to the sides, so the
# side-on camera sees them), dark eye spots; faces -Y; pivot at the body's centre
moth = (part("Body", "uv-sphere --segments 8 --rings 5 --radius 0.5", "0 0 0", "0.17 0.4 0.18", "Moth") +
        part("Head", "ico-sphere --subdivisions 1 --radius 0.5", "0 -0.22 0.02", "0.14 0.12 0.13", "Moth") +
        part("WingF", "uv-sphere --segments 8 --rings 4 --radius 0.5", "0 -0.08 0.2", "0.04 0.32 0.4", "Wing", rot="-18 0 0") +
        part("WingB", "uv-sphere --segments 8 --rings 4 --radius 0.5", "0 0.14 0.17", "0.04 0.28 0.32", "Wing", rot="22 0 0") +
        part("SpotF", "cube --size 1", "0 -0.1 0.24", "0.07 0.1 0.1", "WingSpot") +
        part("AntR", "cube --size 1", "-0.04 -0.31 0.1", "0.045 0.045 0.16", "Moth", rot="-35 0 0") +
        part("AntL", "cube --size 1", "0.04 -0.31 0.1", "0.045 0.045 0.16", "Moth", rot="-35 0 0"))
write("moth", "A dusk moth, the treetops' hovering critter.", ["Moth", "Wing", "WingSpot"],
      moth + join("Body", ["Head", "WingF", "WingB", "SpotF", "AntR", "AntL"], "Moth"))

# a bell-bloom spring: a coiled green stem and a red cup flower with a gold heart; 0.5 tall, 0.6 wide;
# pivot on the ground (the game squashes it on a bounce)
spring = (part("Stem", "cylinder --vertices 6 --radius 0.045 --depth 0.3", "0 0 0.15", None, "Stalk") +
          part("Coil1", "torus --major-segments 8 --minor-segments 4 --major-radius 0.13 --minor-radius 0.04", "0 0 0.08", None, "Stalk") +
          part("Coil2", "torus --major-segments 8 --minor-segments 4 --major-radius 0.13 --minor-radius 0.04", "0 0 0.2", None, "Stalk") +
          part("Cup", "cone --vertices 8 --radius1 0.09 --radius2 0.31 --depth 0.22", "0 0 0.39", None, "Petal") +
          part("Heart", "cylinder --vertices 8 --radius 0.2 --depth 0.04", "0 0 0.48", None, "Gold"))
write("spring", "A bell-bloom: the springy flower.", ["Stalk", "Petal", "Gold"],
      spring + join("Cup", ["Stem", "Coil1", "Coil2", "Heart"], "Spring"))

# a leaf raft (the moving platforms): a broad leaf 1.7 x 0.9, a curled tip, a stalk hanging under
# it; pivot at the middle of its top
write("raft", "A leaf raft: a moving platform.", ["Leafy", "Stalk"],
      part("Leaf", "uv-sphere --segments 10 --rings 4 --radius 0.5", "0 0 -0.07", "1.72 0.9 0.14", "Leafy") +
      ["active Leaf", "mode edit", 'select vert where "pos.x > 0.6"', "translate 0 0 0.04", "mode object"] +
      part("Tip", "cone --vertices 4 --radius1 0.1 --radius2 0 --depth 0.24", "0.92 0 -0.02", None, "Leafy", rot="0 90 0") +
      part("Hang", "cylinder --vertices 5 --radius 0.045 --depth 0.5", "-0.6 0.1 -0.3", None, "Stalk", rot="0 30 0") +
      join("Leaf", ["Tip", "Hang"], "Raft"))

# a bridge plank: a split log 0.96 x 0.8 x 0.14 with rope bindings at both ends; pivot at its top centre
write("plank", "A plank of the crumbling bridge.", ["Wood", "Rope"],
      part("Board", "cube --size 1", "0 0 -0.07", "0.94 0.8 0.14", "Wood") +
      part("RopeA", "cube --size 1", "-0.36 0 -0.07", "0.07 0.84 0.18", "Rope") +
      part("RopeB", "cube --size 1", "0.36 0 -0.07", "0.07 0.84 0.18", "Rope") + join("Board", ["RopeA", "RopeB"], "Plank"))

# a checkpoint bloom: five pink petals round a gold heart, facing the camera; pivot at its base
petals = []
body = part("Heart", "uv-sphere --segments 8 --rings 4 --radius 0.5", "0 -0.05 0.28", "0.17 0.1 0.17", "Gold")
import math
for k in range(5):
    a = math.radians(90 + k * 72)
    x, z = 0.17 * math.cos(a), 0.28 + 0.17 * math.sin(a)
    nm = "P%d" % k
    body += part(nm, "uv-sphere --segments 6 --rings 4 --radius 0.5", "%.3f 0 %.3f" % (x, z), "0.2 0.06 0.13", "Pink",
                 rot="0 %.1f 0" % (-math.degrees(a)))
    petals.append(nm)
body += part("Calyx", "cone --vertices 5 --radius1 0.03 --radius2 0.1 --depth 0.14", "0 0 0.07", None, "Stalk")
write("bloom", "A checkpoint bloom (opens when Pip passes).", ["Gold", "Pink", "Stalk"],
      body + join("Heart", petals + ["Calyx"], "Bloom"))

# the goal pennant: a red leaf-shaped banner 0.95 long and 0.55 tall, flying to +X from the pole;
# pivot at its pole edge (the game hoists it up the pole)
write("pennant", "The goal pennant.", ["Banner", "Gold"],
      part("Flag", "cube --size 1", "0.48 0 0", "0.95 0.05 0.56", "Banner") +
      ["active Flag", "mode edit", 'select vert where "pos.x > 0.4"', "scale 1 1 0.15", "mode object"] +
      part("Edge", "cube --size 1", "0.05 0 0", "0.1 0.07 0.6", "Gold") + join("Flag", ["Edge"], "Pennant"))

# a dust puff
write("puff", "A dust puff.", ["Puff"], part("Puff", "ico-sphere --subdivisions 1 --radius 0.5", "0 0 0", "0.34 0.3 0.28", "Puff"))

# the water band: carried with the camera in whole ripple tiles (4.8 m), 19.2 m wide: a front face from
# its surface (-0.9) down out of the frame, a rippled surface 2.4 m deep, a lily pad per tile
water = (part("Front", "grid --x-subdivisions 1 --y-subdivisions 1 --size 1", "0 -0.75 -2.3", "19.2 2.8 1", "Deep",
              rot="90 0 0") +
         part("Top", "grid --x-subdivisions 4 --y-subdivisions 1 --size 1", "0 0.45 -0.9", "19.2 2.4 1", "Ripple") +
         ["active Top", "mode edit", "select all", "uv cube-project --size 4.8 --center 0 0 0", "mode object"])
pads = []
for k in range(4):
    nm = "Pad%d" % k
    water += part(nm, "cylinder --vertices 8 --radius 0.32 --depth 0.04", "%.2f -0.5 -0.88" % (-7.2 + k * 4.8 + 1.3), "1 0.6 1", "Pad")
    pads.append(nm)
write("water", "The water band under the garden.", ["Deep", "Ripple", "Pad"], water + join("Top", ["Front"] + pads, "Water"))

# far hills: a 24 m strip of soft bluish hills (two copies tile it); pivot at its middle, on the ground
r = random.Random(4)
hills = []
body = []
for k in range(7):
    nm = "H%d" % k
    w = r.uniform(4.5, 6.5); h = r.uniform(1.6, 2.6)
    body += part(nm, "uv-sphere --segments 10 --rings 6 --radius 0.5", "%.2f 0 0" % (-12 + k * 4.0 + r.uniform(-0.5, 0.5)),
                 "%.2f 1.0 %.2f" % (w, 2 * h), "Hill",
                 extra=["active " + nm, "mode edit", 'select face where "pos.z < 0.0 || normal.y > 0.3"', "delete only-faces",
                        'select face where "pos.z > %.2f"' % (h * 0.72), "material assign HillTop", "mode object"])
    hills.append(nm)
write("hills", "Far hills (parallax).", ["Hill", "HillTop"], body + join(hills[0], hills[1:], "Hills"))

# a grove: a 24 m strip of round tree crowns on short trunks (the middle parallax layer)
body = []; names = []
for k in range(9):
    nm = "G%d" % k
    s = r.uniform(1.3, 2.0)
    x = -12 + k * 2.75 + r.uniform(-0.4, 0.4)
    body += part(nm, "ico-sphere --subdivisions 2 --radius 0.5", "%.2f 0 %.2f" % (x, 1.2 + s * 0.5), "%.2f 0.8 %.2f" % (s * 1.4, s),
                 "Grove", extra=["active " + nm, "mode edit", 'select face where "normal.y > 0.3"', "delete only-faces", "mode object"])
    names.append(nm)
write("grove", "A grove of far trees (parallax).", ["Grove"], body + join(names[0], names[1:], "Grove"))

# a cloud: four puffs
body = []; names = []
for k, (x, z, s) in enumerate(((-0.9, 0.0, 1.0), (0.0, 0.3, 1.4), (0.9, 0.05, 1.1), (0.3, -0.1, 1.0))):
    nm = "Q%d" % k
    body += part(nm, "ico-sphere --subdivisions 1 --radius 0.5", "%.2f 0 %.2f" % (x, z), "%.2f 0.5 %.2f" % (s * 1.3, s * 0.85), "Cloud",
                 extra=["active " + nm, "mode edit", 'select face where "normal.y > 0.3"', "delete only-faces", "mode object"])
    names.append(nm)
write("cloud", "A cloud.", ["Cloud"], body + join(names[0], names[1:], "Cloud"))
print("wrote seed pop shellbug moth spring raft plank bloom pennant puff water hills grove cloud")
